self.example:
#include <cinux/singleton.hpp>

#include <type_traits>

using namespace cinux::base;

class Counter : public Singleton<Counter> {
public:
    unsigned long long total = 0;
};

static_assert(std::is_trivially_destructible_v<Counter>);  // self() 的断言前提，不能带析构钩子

void Example() {
    Counter& counter = Counter::self();              // 执行前就初始化好的唯一实例
    counter.total = 7;
    const bool kSame = &Counter::self() == &counter;  // true · 两次调用拿到同一份存储
    (void)kSame;
}

guard.example:
#include <cinux/spin_mutex.hpp>

using namespace cinux::base;

unsigned long long gShared = 0;

void Example() {
    static SpinMutex kMutex;

    {
        auto held = kMutex.guard();  // 构造即加锁
        gShared += 1;
    }  // 离开作用域，析构解锁
}

lock.example:
#include <cinux/spin_mutex.hpp>

using namespace cinux::base;

unsigned long long gShared = 0;

void Example() {
    static SpinMutex kMutex;  // 一把自旋锁，守着下面的共享计数

    kMutex.lock();  // 自旋到取得独占所有权
    gShared += 1;
    kMutex.unlock();  // 发布这一笔修改，放开所有权
}
